REPORTS = os.path.abspath("./data/reports")

@app.route("/download")
def download():
    filename = request.args.get("filename", "")
    path = os.path.join(REPORTS, filename)

    # Ensure the file is within the REPORTS directory to prevent directory traversal
    if not os.path.isabs(path):
        real_path = os.path.realpath(path)
        real_reports = os.path.realpath(REPORTS)
        if not real_path.startswith(real_reports + os.sep) and real_path != real_reports:
            abort(403)

    if not os.path.isfile(path):
        abort(404)

    return send_file(path)
