import os
from flask import Flask, request, abort, Response

app = Flask(__name__)

@app.route("/logs")
def logs():
    name = request.args.get("file", "")

    # Validate the filename to prevent directory traversal attacks
    if not name or '..' in name or name.startswith('/'):
        abort(400)

    # Construct the path safely by ensuring it stays within the base directory
    base_dir = "./logs"
    if not os.path.isdir(base_dir):
        abort(500)

    target_path = os.path.join(base_dir, name)

    # Double-check that the resolved path is actually within the base directory
    real_base = os.path.realpath(base_dir)
    real_target = os.path.realpath(target_path)

    if not real_target.startswith(real_base + os.sep) and real_target != real_base:
        abort(403)

    if not os.path.isfile(target_path):
        abort(404)

    try:
        with open(target_path, "r", encoding="utf-8") as fh:
            lines = fh.readlines()
        return Response("".join(lines[-10:]), mimetype="text/plain")
    except Exception:
        abort(500)
