    char *value_start = eq + 1;
    size_t value_len = strlen(value_start);
    if (value_len >= sizeof(value)) {
        fprintf(stderr, "value too long\n");
        return 1;
    }
    strcpy(value, value_start);

    printf("key: %s\n", key);
    printf("value: %s\n", value);

